from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy.orm import Session
from backend.database import get_db
from backend.models.inventory import Inventory
from backend.schemas.inventory import InventoryCreate, InventoryUpdate, InventoryResponse

router = APIRouter()

@router.post("", response_model=InventoryResponse, status_code=200)
def create_inventory(item: InventoryCreate, db: Session = Depends(get_db)):
    existing = db.query(Inventory).filter(Inventory.product_name == item.product_name).first()
    if existing:
        raise HTTPException(status_code=400, detail="already exists")
    new_inv = Inventory(**item.model_dump())
    db.add(new_inv)
    db.commit()
    db.refresh(new_inv)
    return new_inv

@router.get("", response_model=list[InventoryResponse], status_code=200)
def list_inventory(db: Session = Depends(get_db)):
    return db.query(Inventory).all()

@router.get("/{product_name}", response_model=InventoryResponse, status_code=200)
def get_inventory(product_name: str, db: Session = Depends(get_db)):
    inv = db.query(Inventory).filter(Inventory.product_name == product_name).first()
    if not inv:
        raise HTTPException(status_code=404, detail="Inventory not found")
    return inv

@router.patch("/{product_name}", response_model=InventoryResponse, status_code=200)
def update_inventory(product_name: str, update_data: InventoryUpdate, db: Session = Depends(get_db)):
    inv = db.query(Inventory).filter(Inventory.product_name == product_name).first()
    if not inv:
        raise HTTPException(status_code=404, detail="Inventory not found")
    for key, value in update_data.model_dump(exclude_unset=True).items():
        setattr(inv, key, value)
    db.commit()
    db.refresh(inv)
    return inv

