from typing import List, Optional
from backend.models.order import Order
from backend.schemas.order import OrderCreate, OrderResponse
from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.orm import Session
from datetime import datetime

from backend.database import get_db
from backend.models.order import Order, OrderStatus
from backend.schemas.order import OrderCreate, OrderResponse, OrderUpdateStatus
from backend.models.inventory import Inventory

router = APIRouter()

@router.post("", response_model=OrderResponse, status_code=status.HTTP_200_OK)
def create_order(order_data: OrderCreate, db: Session = Depends(get_db)):
    # Inventory check and deduction
    if order_data.items:
        for item in order_data.items:
            product_name = item.get("product_name")
            quantity = item.get("quantity", 0)

            inv = db.query(Inventory).filter(Inventory.product_name == product_name).first()
            if not inv:
                raise HTTPException(
                    status_code=status.HTTP_400_BAD_REQUEST,
                    detail=f"Product {product_name} does not exist in inventory"
                )
            if inv.quantity < quantity:
                raise HTTPException(
                    status_code=status.HTTP_400_BAD_REQUEST,
                    detail="Insufficient stock"
                )
            inv.quantity -= quantity

    db_order = Order(
        user_id=order_data.user_id,
        status=OrderStatus.PENDING.value,
        total_amount=order_data.total_amount,
        items=order_data.items,
        created_at=datetime.utcnow()
    )
    db.add(db_order)
    db.commit()
    db.refresh(db_order)
    return db_order

@router.get("", response_model=List[OrderResponse], status_code=status.HTTP_200_OK)
def list_orders(db: Session = Depends(get_db)):
    orders = db.query(Order).all()
    return orders

@router.get("/{order_id}", response_model=OrderResponse, status_code=status.HTTP_200_OK)
def get_order(order_id: int, db: Session = Depends(get_db)):
    order = db.query(Order).filter(Order.id == order_id).first()
    if not order:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Order not found")
    return order

@router.put("/{order_id}/status", response_model=OrderResponse, status_code=status.HTTP_200_OK)
def update_order_status(order_id: int, status_update: OrderUpdateStatus, db: Session = Depends(get_db)):
    order = db.query(Order).filter(Order.id == order_id).first()
    if not order:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Order not found")

    try:
        current_enum = OrderStatus(order.status)
        allowed_next = current_enum.next_states()
        if status_update.new_status not in allowed_next:
            raise HTTPException(
                status_code=status.HTTP_422_UNPROCESSABLE_ENTITY,
                detail=f"Invalid status transition from {order.status} to {status_update.new_status}"
            )
    except ValueError:
        raise HTTPException(status_code=status.HTTP_422_UNPROCESSABLE_ENTITY, detail="Invalid current status")

    order.status = status_update.new_status
    db.commit()
    db.refresh(order)
    return order

@router.delete("/{order_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_order(order_id: int, db: Session = Depends(get_db)):
    order = db.query(Order).filter(Order.id == order_id).first()
    if not order:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Order not found")
    db.delete(order)
    db.commit()
    return
